"use client";

import { ClerkProvider, ClerkLoaded, ClerkLoading } from "@clerk/nextjs";
import Loader from "../components/Loader";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import DashboardPreload from "../dashboard-preload";
import HeadScript from "./head-script";

// Import dashboard-specific styles
import "../styles/dashboard-background.css";
import "../styles/dashboard/dashboard-typography.css";
import "../styles/layout-transitions.css";
import "../styles/dashboard-preload.css";

// Use dynamic imports for client components
const HydrationErrorFix = dynamic(() => import('../components/client/HydrationErrorFix'));
const SVDAttributeRemover = dynamic(() => import('../components/client/SVDAttributeRemover'));
const AttributeDebugger = dynamic(() => import('../components/client/AttributeDebugger'));
const ScriptMonitor = dynamic(() => import('../components/client/ScriptMonitor'));
const DirectHydrationFix = dynamic(() => import('../components/client/DirectHydrationFix'));

export default function DashboardLayout({ children }) {
  const pathname = usePathname();
  const [isLoading, setIsLoading] = useState(true);

  // Add a loading state to prevent flashing
  useEffect(() => {
    // Set loading to false after a short delay
    const timer = setTimeout(() => {
      setIsLoading(false);

      // Only add classes after hydration is complete
      // This prevents hydration mismatches
      document.body.classList.add('dashboard-active');
      document.documentElement.classList.add('dashboard-page');
    }, 100);

    // Use data attributes instead of classes to avoid hydration mismatches
    document.documentElement.setAttribute('data-dashboard', 'true');

    // Remove pattern-bg class from the root background element
    const patternBg = document.querySelector('.pattern-bg');
    if (patternBg) {
      patternBg.style.display = 'none';
    }

    // Add data attribute to the root layout
    const rootLayout = document.querySelector('body > div');
    if (rootLayout) {
      rootLayout.setAttribute('data-layout', 'root');
    }

    // Add preload script to head if it doesn't exist
    if (!document.getElementById('dashboard-preload-script')) {
      const script = document.createElement('script');
      script.id = 'dashboard-preload-script';
      script.src = '/dashboard-preload.js';
      script.async = false;
      document.head.appendChild(script);
    }

    return () => {
      clearTimeout(timer);

      // Only remove classes and attributes if we're navigating away from dashboard
      if (!pathname.includes('/dashboard')) {
        document.body.classList.remove('dashboard-active');
        document.documentElement.classList.remove('dashboard-page');
        document.documentElement.removeAttribute('data-dashboard');

        // Remove data attribute from the root layout
        if (rootLayout) {
          rootLayout.removeAttribute('data-layout');
        }

        // Restore pattern-bg when leaving dashboard
        if (patternBg) {
          patternBg.style.display = 'block';
        }

        // Remove the preload script
        const script = document.getElementById('dashboard-preload-script');
        if (script) {
          script.remove();
        }
      }
    };
  }, [pathname]);

  return (
    <div className="dashboard-root">
      {/* Critical CSS loaded directly in the head */}
      <link rel="stylesheet" href="/dashboard-critical.css" />

      {/* Scripts to prevent flashing during hard reloads */}
      <HeadScript />
      <DashboardPreload />

      <HydrationErrorFix />
      <ScriptMonitor />
      <AttributeDebugger />
      <SVDAttributeRemover />
      <DirectHydrationFix>
        <ClerkProvider>
          <div className="relative min-h-screen flex flex-col">
            {/* Dashboard-specific background */}
            <div className="dashboard-bg"></div>

            <ClerkLoading>
              <Loader />
            </ClerkLoading>

            <ClerkLoaded>
              {/* Apply fade-in transition to prevent flashing */}
              <div
                className={`transition-opacity duration-300 layout-transition ${
                  isLoading ? 'opacity-0' : 'opacity-100'
                }`}
                style={{
                  transitionDelay: isLoading ? '0ms' : '50ms',
                  willChange: 'opacity, transform'
                }}
              >
                <main className="relative z-10 flex-grow">
                  {children}
                </main>
              </div>
            </ClerkLoaded>
          </div>
        </ClerkProvider>
      </DirectHydrationFix>
    </div>
  );
}
